import os
import unicodedata
import hashlib
import hmac
import re
from pathlib import PurePosixPath
from typing import Optional
import secrets

# Secure file serving module with path traversal protection

SECRET_KEY = os.environ.get('APP_SECRET_KEY', secrets.token_hex(32))
BASE_DIR = '/srv/documents'
ALLOWED_EXTENSIONS = {'.pdf', '.txt', '.docx', '.xlsx', '.png', '.jpg'}


def generate_access_token(username: str, filepath: str) -> str:
    """Generate HMAC token for authorized file access."""
    msg = f"{username}:{filepath}".encode('utf-8')
    return hmac.new(SECRET_KEY.encode(), msg, hashlib.sha256).hexdigest()


def verify_access_token(username: str, filepath: str, token: str) -> bool:
    """Verify HMAC token for file access authorization."""
    expected = generate_access_token(username, filepath)
    return hmac.compare_digest(expected, token)


def sanitize_filename(filename: str) -> str:
    """Remove potentially dangerous characters from filename."""
    # Strip null bytes
    filename = filename.replace('\x00', '')
    # Remove control characters
    filename = ''.join(c for c in filename if unicodedata.category(c)[0] != 'C')
    return filename


def validate_path_components(filepath: str) -> bool:
    """Validate that path components don't contain traversal sequences."""
    # Check for obvious traversal patterns
    if '..' in filepath:
        return False
    if filepath.startswith('/'):
        return False
    # Check each component
    parts = filepath.split('/')
    for part in parts:
        if part in ('.', '..', ''):
            return False
        # Block hidden files
        if part.startswith('.'):
            return False
    return True


def check_extension(filepath: str) -> bool:
    """Verify file has an allowed extension."""
    ext = os.path.splitext(filepath)[1].lower()
    return ext in ALLOWED_EXTENSIONS


def normalize_unicode(text: str) -> str:
    """Normalize unicode to NFC form for consistent handling."""
    return unicodedata.normalize('NFC', text)


def resolve_file_path(user_input: str) -> Optional[str]:
    """Safely resolve a user-provided path to an absolute filesystem path.

    Security measures:
    1. Sanitize filename (remove null bytes, control chars)
    2. Validate path components (no traversal)
    3. Check file extension against allowlist
    4. Normalize unicode for consistent representation
    5. Verify resolved path is within BASE_DIR
    """
    # Step 1: Sanitize
    cleaned = sanitize_filename(user_input)

    # Step 2: Validate path components
    if not validate_path_components(cleaned):
        return None

    # Step 3: Check extension
    if not check_extension(cleaned):
        return None

    # Step 4: Unicode normalization (NFKC decomposes compatibility characters)
    normalized = unicodedata.normalize('NFKC', cleaned)

    # Step 5: Construct and verify final path
    final_path = os.path.join(BASE_DIR, normalized)
    real_path = os.path.realpath(final_path)

    # Ensure we're still within BASE_DIR
    if not real_path.startswith(BASE_DIR):
        return None

    return real_path


def serve_file(username: str, filepath: str, token: str) -> dict:
    """Serve a file to an authenticated user.

    Args:
        username: Authenticated username
        filepath: Relative path to requested file
        token: HMAC access token

    Returns:
        Dict with file content or error
    """
    if not username or not filepath or not token:
        return {'error': 'Missing required parameters', 'status': 400}

    # Verify access token
    if not verify_access_token(username, filepath, token):
        return {'error': 'Invalid access token', 'status': 403}

    # Resolve the file path securely
    resolved = resolve_file_path(filepath)
    if resolved is None:
        return {'error': 'Invalid file path', 'status': 400}

    # Check file exists
    if not os.path.isfile(resolved):
        return {'error': 'File not found', 'status': 404}

    # Read and return file
    try:
        with open(resolved, 'rb') as f:
            content = f.read()
        return {
            'content': content,
            'path': resolved,
            'status': 200
        }
    except PermissionError:
        return {'error': 'Access denied', 'status': 403}
    except IOError:
        return {'error': 'Read error', 'status': 500}
